.sl-article-reader {
    background-color: var(--smartlearn-bg);
    padding-bottom: 5rem;
}

.sl-article-reader .sl-text-primary { color: var(--smartlearn-primary) !important; }
.sl-article-reader .sl-text-emphasis { color: var(--smartlearn-text) !important; }
.sl-article-reader .sl-text-muted { color: var(--smartlearn-text-muted) !important; }
.sl-article-reader .sl-bg-main { background-color: var(--smartlearn-bg) !important; }
.sl-article-reader .sl-bg-card { background-color: var(--smartlearn-card-bg) !important; border: 1px solid var(--smartlearn-card-border) !important; }
.sl-article-reader .sl-border { border-color: var(--smartlearn-card-border) !important; }
.sl-article-reader .sl-tracking-wide { letter-spacing: 0.1em; }

.sl-article-reader .sl-focus-ring:focus-visible {
    outline: 3px solid var(--smartlearn-primary);
    outline-offset: 3px;
}

.sl-article-reader .sl-reading-progress-container {
    top: var(--smartlearn-navbar-height, 64px);
    z-index: 1020;
    height: 4px;
    background-color: var(--smartlearn-card-bg);
}
.sl-article-reader .sl-reading-progress-bar {
    width: 0%;
    background-color: var(--smartlearn-primary);
    transition: width 0.1s ease-out;
}

.sl-article-reader .sl-reader-content p { margin-bottom: 1.75rem; }
.sl-article-reader .sl-reader-content ul { padding-inline-start: 1.5rem; }

/* Logical Drop Cap (disabled in RTL for Arabic ligatures) */
.sl-article-reader .sl-drop-cap::first-letter {
    float: inline-start;
    font-size: 4.5rem;
    line-height: 0.8;
    padding-top: 0.2rem;
    padding-inline-end: 0.75rem;
    font-weight: 800;
    color: var(--smartlearn-primary);
}
[dir="rtl"] .sl-article-reader .sl-drop-cap::first-letter {
    float: none;
    font-size: inherit;
    line-height: inherit;
    padding: 0;
    font-weight: inherit;
    color: inherit;
}

.sl-article-reader .sl-blockquote {
    border-inline-start: 4px solid var(--smartlearn-primary) !important;
    transition: transform 0.3s ease;
}
@media (hover: hover) and (prefers-reduced-motion: no-preference) {
    .sl-article-reader .sl-blockquote:hover {
        transform: translateY(-3px);
    }
}

.sl-article-reader .sl-btn-cta {
    background-color: var(--smartlearn-btn-bg);
    color: var(--smartlearn-btn-text);
    border: 1px solid transparent;
    transition: background-color 0.2s ease;
}
.sl-article-reader .sl-btn-cta:hover,
.sl-article-reader .sl-btn-cta:focus-visible {
    background-color: var(--smartlearn-btn-hover-bg);
    color: var(--smartlearn-btn-text);
}

@media (prefers-reduced-motion: reduce) {
    .sl-article-reader .sl-reading-progress-bar,
    .sl-article-reader .sl-blockquote,
    .sl-article-reader .sl-btn-cta { transition: none; }
}

js:
(function() {
    function init() {
        var sections = document.querySelectorAll('.sl-article-reader');
        var tracked = [];
        sections.forEach(function(section) {
            if (section.dataset.slInit === '1') return;
            section.dataset.slInit = '1';
            var bar = section.querySelector('.sl-reading-progress-bar');
            if (bar) tracked.push({ section: section, bar: bar });
        });
        if (tracked.length === 0) return;

        var updateProgress = function() {
            var vh = window.innerHeight;
            tracked.forEach(function(item) {
                var rect = item.section.getBoundingClientRect();
                if (rect.top >= 0) {
                    item.bar.style.width = '0%';
                    return;
                }
                var scrollable = Math.max(1, rect.height - vh);
                var pct = Math.max(0, Math.min(100, (-rect.top / scrollable) * 100));
                item.bar.style.width = pct.toFixed(2) + '%';
            });
        };

        var ticking = false;
        var onScroll = function() {
            if (ticking) return;
            ticking = true;
            requestAnimationFrame(function() {
                ticking = false;
                updateProgress();
            });
        };

        window.addEventListener('scroll', onScroll, { passive: true });
        window.addEventListener('resize', onScroll, { passive: true });
        updateProgress();
    }
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();
